function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}
function failure(requestId, category) {
  return {
    ok: false,
    lookup_input_valid: false,
    status_code: 500,
    public_response: {
      error: { code: 'INTERNAL_ERROR', message: 'The intelligence lookup could not be completed.', details: [] },
      request_id: typeof requestId === 'string' && requestId ? requestId : null,
      timestamp: new Date().toISOString()
    },
    internal_diagnostics: {
      entity_lookup: { failure_stage: 'input_validation', error_category: category }
    }
  };
}
function validDomain(value) {
  return typeof value === 'string' &&
    value.length <= 253 &&
    /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+(?:[a-z]{2,63}|xn--[a-z0-9-]{2,59})$/.test(value);
}
try {
  const raw = $input.first().json;
  const allowedRoot = new Set(['context', 'trusted_domain_candidates']);
  if (!isRecord(raw) || Object.keys(raw).some((key) => !allowedRoot.has(key))) {
    return [{ json: failure(null, 'invalid_lookup_envelope') }];
  }
  const context = raw.context;
  const requestId = isRecord(context) ? context.request_id : null;
  if (!isRecord(context) || typeof context.content !== 'string' || !context.content.trim() || context.content.length > 20000) {
    return [{ json: failure(requestId, 'invalid_lookup_context') }];
  }
  const trustedDomainCandidates = raw.trusted_domain_candidates === undefined ? [] : raw.trusted_domain_candidates;
  if (!Array.isArray(trustedDomainCandidates) || trustedDomainCandidates.length > 5 ||
      trustedDomainCandidates.some((value) => !validDomain(value)) ||
      new Set(trustedDomainCandidates).size !== trustedDomainCandidates.length) {
    return [{ json: failure(requestId, 'invalid_trusted_domain_candidates') }];
  }
  return [{ json: {
    ok: true,
    lookup_input_valid: true,
    context: JSON.parse(JSON.stringify(context)),
    trusted_domain_candidates: [...trustedDomainCandidates]
  } }];
} catch {
  return [{ json: failure(null, 'lookup_input_validation_failure') }];
}

const MAX_ENTITIES_PER_TYPE = 10;
const MAX_ENTITIES_TOTAL = 20;
const SUPPORTED_ENTITY_TYPES = new Set(['phone', 'bank_account', 'domain']);

function normalizePhone(value) {
  if (typeof value !== 'string') return null;
  const compact = value.replace(/[\s().-]/g, '');
  let normalized;
  if (compact.startsWith('+66')) normalized = `0${compact.slice(3)}`;
  else if (compact.startsWith('0066')) normalized = `0${compact.slice(4)}`;
  else normalized = compact;
  return /^0[689]\d{8}$/.test(normalized) ? normalized : null;
}

function normalizeBankAccount(value) {
  if (typeof value !== 'string') return null;
  const normalized = value.replace(/[\s-]/g, '');
  return /^\d{10,15}$/.test(normalized) ? normalized : null;
}

function isIpAddress(hostname) {
  if (/^\d{1,3}(?:\.\d{1,3}){3}$/.test(hostname)) return true;
  return hostname.includes(':');
}

function normalizeDomain(value) {
  if (typeof value !== 'string') return null;
  let candidate = value.trim().replace(/[),;!?\]}>'"]+$/g, '');
  if (!candidate) return null;

  const schemeMatch = candidate.match(/^([a-z][a-z0-9+.-]*):\/\//i);
  if (schemeMatch) {
    const scheme = schemeMatch[1].toLowerCase();
    if (scheme !== 'http' && scheme !== 'https') return null;
    candidate = candidate.slice(schemeMatch[0].length);
  }

  let authority = candidate.split(/[/?#]/, 1)[0];
  if (!authority) return null;
  authority = authority.split('@').pop();

  let hostname;
  if (authority.startsWith('[')) {
    const closingBracket = authority.indexOf(']');
    if (closingBracket < 0) return null;
    hostname = authority.slice(1, closingBracket);
  } else {
    hostname = authority.split(':', 1)[0];
  }

  hostname = String(hostname || '').toLowerCase().replace(/\.$/, '');
  if (!hostname || hostname === 'localhost' || hostname.endsWith('.localhost') || isIpAddress(hostname)) return null;
  if (hostname.length > 253 || !hostname.includes('.')) return null;
  const labels = hostname.split('.');
  if (labels.some((label) => !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label))) return null;
  const topLevelLabel = labels[labels.length - 1];
  if (!/^[a-z]{2,63}$/.test(topLevelLabel) && !/^xn--[a-z0-9-]{2,59}$/.test(topLevelLabel)) return null;
  return hostname;
}

function addCandidate(candidates, entityType, normalizedValue, position) {
  if (!SUPPORTED_ENTITY_TYPES.has(entityType) || !normalizedValue) return;
  const key = `${entityType}:${normalizedValue}`;
  const existing = candidates.get(key);
  if (!existing || position < existing.position) {
    candidates.set(key, { entity_type: entityType, normalized_value: normalizedValue, position });
  }
}

function extractEntities(content, trustedDomainCandidates) {
  if (typeof content !== 'string' || !content.trim()) return [];
  const candidates = new Map();
  const phoneValues = new Set();
  const phoneRanges = [];

  if (Array.isArray(trustedDomainCandidates)) {
    trustedDomainCandidates.slice(0, MAX_ENTITIES_PER_TYPE).forEach((value, index) => {
      const normalized = normalizeDomain(value);
      if (normalized) addCandidate(candidates, 'domain', normalized, -1000 + index);
    });
  }

  const phonePattern = /(?<!\d)(?:\+66|0066|0)(?:[\s().-]*\d){8,10}(?!\d)/g;
  for (const match of content.matchAll(phonePattern)) {
    const normalized = normalizePhone(match[0]);
    if (!normalized) continue;
    phoneValues.add(normalized);
    phoneRanges.push([match.index, match.index + match[0].length]);
    addCandidate(candidates, 'phone', normalized, match.index);
  }

  const bankPattern = /(?<!\d)(?:\d[\s-]*){10,15}(?!\d)/g;
  for (const match of content.matchAll(bankPattern)) {
    const overlapsPhone = phoneRanges.some(([start, end]) => (
      match.index < end && match.index + match[0].length > start
    ));
    if (overlapsPhone) continue;
    const normalized = normalizeBankAccount(match[0]);
    if (!normalized || phoneValues.has(normalized)) continue;
    const start = Math.max(0, match.index - 60);
    const end = Math.min(content.length, match.index + match[0].length + 60);
    const nearby = content.slice(start, end);
    const hasBankContext = /(เลข(?:ที่)?บัญชี|บัญชี(?:ธนาคาร)?|bank\s*account|account\s*(?:number|no\.?))/i.test(nearby);
    const visiblyGrouped = /[\s-]/.test(match[0].trim());
    if (!hasBankContext && !visiblyGrouped) continue;
    addCandidate(candidates, 'bank_account', normalized, match.index);
  }

  const schemePattern = /\b[a-z][a-z0-9+.-]*:\/\/[^\s<>]+/gi;
  const masked = [...content];
  const unsupportedSchemeRanges = [];
  for (const match of content.matchAll(schemePattern)) {
    const normalized = normalizeDomain(match[0]);
    if (normalized) {
      addCandidate(candidates, 'domain', normalized, match.index);
      for (let index = match.index; index < match.index + match[0].length; index += 1) masked[index] = ' ';
    } else if (!/^https?:\/\//i.test(match[0])) {
      unsupportedSchemeRanges.push([match.index, match.index + match[0].length]);
    }
  }

  const plainText = masked.join('');
  const plainDomainPattern = /(?<![@\w-])(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}(?![\w-])/gi;
  for (const match of plainText.matchAll(plainDomainPattern)) {
    const insideUnsupportedScheme = unsupportedSchemeRanges.some(([start, end]) => (
      match.index >= start && match.index < end
    ));
    if (insideUnsupportedScheme) continue;
    const normalized = normalizeDomain(match[0]);
    if (normalized) addCandidate(candidates, 'domain', normalized, match.index);
  }

  const typeCounts = new Map();
  const output = [];
  const ordered = [...candidates.values()].sort((left, right) => (
    left.position - right.position || left.entity_type.localeCompare(right.entity_type)
  ));
  for (const entity of ordered) {
    if (output.length >= MAX_ENTITIES_TOTAL) break;
    const count = typeCounts.get(entity.entity_type) || 0;
    if (count >= MAX_ENTITIES_PER_TYPE) continue;
    typeCounts.set(entity.entity_type, count + 1);
    output.push({ entity_type: entity.entity_type, normalized_value: entity.normalized_value });
  }
  return output;
}

function redactEntity(entityType, normalizedValue) {
  if (entityType === 'domain') return normalizedValue;
  if (entityType === 'phone') {
    return normalizedValue.length >= 7
      ? `${normalizedValue.slice(0, 3)}***${normalizedValue.slice(-4)}`
      : '[REDACTED_PHONE]';
  }
  if (entityType === 'bank_account') {
    return normalizedValue.length >= 4
      ? `${'*'.repeat(Math.max(6, normalizedValue.length - 4))}${normalizedValue.slice(-4)}`
      : '[REDACTED_ACCOUNT]';
  }
  return '[REDACTED]';
}

try {
  const data = JSON.parse(JSON.stringify($input.first().json));
  if (data.ok !== true || !data.context || typeof data.context.content !== 'string') throw new Error('Validated lookup input is unavailable.');
  const entities = extractEntities(data.context.content, data.trusted_domain_candidates);
  return [{ json: {
    ok: true,
    context: data.context,
    entities,
    lookup_required: entities.length > 0,
    internal_diagnostics: {
      entity_lookup: { extraction_performed: true, entity_count: entities.length }
    }
  } }];
} catch {
  return [{ json: {
    ok: false,
    lookup_required: false,
    status_code: 500,
    public_response: {
      error: { code: 'INTERNAL_ERROR', message: 'The intelligence lookup could not be completed.', details: [] },
      request_id: null,
      timestamp: new Date().toISOString()
    },
    internal_diagnostics: {
      entity_lookup: { failure_stage: 'entity_extraction', error_category: 'entity_extraction_failure' }
    }
  } }];
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}
function redact(entityType, value) {
  const normalized = typeof value === 'string' ? value : '';
  if (entityType === 'domain') return normalized;
  if (entityType === 'phone') return normalized.length >= 7 ? normalized.slice(0, 3) + '***' + normalized.slice(-4) : '[REDACTED_PHONE]';
  if (entityType === 'bank_account') return normalized.length >= 4 ? '*'.repeat(Math.max(6, normalized.length - 4)) + normalized.slice(-4) : '[REDACTED_ACCOUNT]';
  return '[REDACTED]';
}
function safeFailure(requestId, stage, category) {
  return {
    ok: false,
    status_code: stage === 'database_lookup' ? 503 : 500,
    public_response: {
      error: {
        code: stage === 'database_lookup' ? 'INTELLIGENCE_LOOKUP_UNAVAILABLE' : 'INTERNAL_ERROR',
        message: stage === 'database_lookup'
          ? 'The intelligence lookup service is temporarily unavailable.'
          : 'The intelligence lookup could not be completed.',
        details: []
      },
      request_id: typeof requestId === 'string' && requestId ? requestId : null,
      timestamp: new Date().toISOString()
    },
    internal_diagnostics: {
      entity_lookup: { failure_stage: stage, error_category: category }
    }
  };
}
try {
  const incoming = $input.all().map((item) => item.json);
  const first = incoming[0] || {};
  if (first.ok === false && first.public_response) {
    const stage = first.internal_diagnostics && first.internal_diagnostics.entity_lookup && first.internal_diagnostics.entity_lookup.failure_stage;
    const category = first.internal_diagnostics && first.internal_diagnostics.entity_lookup && first.internal_diagnostics.entity_lookup.error_category;
    return [{ json: safeFailure(first.public_response.request_id, stage || 'input_validation', category || 'invalid_lookup_input') }];
  }

  let extracted;
  try { extracted = $('Extract and Normalize Entities').first().json; } catch { extracted = first; }
  const context = isRecord(extracted.context) ? extracted.context : null;
  const requestId = context && context.request_id;
  if (!context || !Array.isArray(extracted.entities)) {
    return [{ json: safeFailure(requestId, 'result_normalization', 'missing_extraction_context') }];
  }
  if (incoming.some((row) => row && row.error)) {
    return [{ json: safeFailure(requestId, 'database_lookup', 'database_unavailable') }];
  }

  const rowsByKey = new Map();
  for (const row of incoming) {
    if (!isRecord(row) || typeof row.entity_type !== 'string' || typeof row.normalized_value !== 'string') continue;
    rowsByKey.set(row.entity_type + ':' + row.normalized_value, row);
  }
  const allowedStatuses = new Set(['reported', 'suspected', 'confirmed_scam', 'cleared']);
  const entities = extracted.entities.map((entity) => {
    const row = rowsByKey.get(entity.entity_type + ':' + entity.normalized_value);
    const matched = Boolean(row && allowedStatuses.has(row.status));
    const reportCount = matched ? Number(row.report_count) : null;
    const confidence = matched && row.confidence_score !== null && row.confidence_score !== undefined
      ? Number(row.confidence_score)
      : null;
    return {
      entity_type: entity.entity_type,
      redacted_value: redact(entity.entity_type, entity.normalized_value),
      matched,
      status: matched ? row.status : null,
      report_count: matched && Number.isInteger(reportCount) && reportCount >= 0 ? reportCount : null,
      confidence_score: matched && Number.isFinite(confidence) && confidence >= 0 && confidence <= 1 ? confidence : null
    };
  });
  const matchedCount = entities.filter((entity) => entity.matched).length;
  const safeContext = {
    request_id: typeof context.request_id === 'string' ? context.request_id : null,
    analysis_id: typeof context.analysis_id === 'string' ? context.analysis_id : null,
    input_type: typeof context.input_type === 'string' ? context.input_type : null,
    language: typeof context.language === 'string' ? context.language : null,
    accepted_at: typeof context.accepted_at === 'string' ? context.accepted_at : null,
    accepted_epoch_ms: Number.isFinite(context.accepted_epoch_ms) ? context.accepted_epoch_ms : null,
    requested_output_language: typeof context.requested_output_language === 'string' ? context.requested_output_language : null
  };
  return [{ json: {
    ok: true,
    context: safeContext,
    intelligence: { entities },
    internal_diagnostics: {
      entity_lookup: {
        lookup_performed: extracted.entities.length > 0,
        entity_count: entities.length,
        matched_count: matchedCount
      }
    }
  } }];
} catch {
  return [{ json: safeFailure(null, 'result_normalization', 'result_normalization_failure') }];
}
